import { useEffect, useState } from 'react'
import { clocks, type Clock } from './data'

const Timekeeper = ({ message, compact=false }: {message:string; compact?:boolean}) => <aside className={'guide '+(compact?'compact':'')} aria-label="Timekeeper anlatıcı">
  <div className="bubble"><span className="eyebrow">TIMEKEEPER · 01</span><p>{message}</p><i /></div>
  <div className="sprite-wrap"><span className="spark s1">✦</span><span className="spark s2">✧</span><img src="/assets/timekeeper/timekeeper-idle.webp" alt="Timekeeper Cookie" /></div>
</aside>

const ClockFace = ({className=''}) => <div className={'clock-face '+className} aria-hidden="true"><div className="roman r12">XII</div><div className="roman r3">III</div><div className="roman r6">VI</div><div className="roman r9">IX</div><span className="hand hour"/><span className="hand minute"/><b className="pivot"/></div>

function App(){
 const [loading,setLoading]=useState(true), [selected,setSelected]=useState<Clock>(clocks[0]), [timeless,setTimeless]=useState(false), [menu,setMenu]=useState(false)
 useEffect(()=>{ const t=window.setTimeout(()=>setLoading(false),4200); return()=>clearTimeout(t)},[])
 const restart=()=>{setLoading(true); window.setTimeout(()=>setLoading(false),4200)}
 return <main className={timeless?'timeless':''}>
 {loading && <section className="loader" aria-live="polite"><div className="loader-rings"/><ClockFace className="loader-clock"/><div className="loader-copy"><span>SELEN ÖNÜGÖREN</span><strong>ZAMAN BAŞLATILIYOR</strong><small>Time is the only thing we can never rewind.</small></div><div className="load-meter">∞ <em>100</em></div></section>}
 <nav><a className="logo" href="#top">TIME<span>.</span></a><button className="hamb" onClick={()=>setMenu(!menu)} aria-label="Menüyü aç">{menu?'×':'☰'}</button><div className={menu?'links open':'links'}><a href="#story">STORY</a><a href="#history">HISTORY</a><a href="#lab">CLOCKS</a><a href="#future">FUTURE</a><a href="#about">ABOUT</a></div></nav>
 <section id="top" className="hero"><div className="grid"/><div className="hero-copy"><span className="eyebrow">MUSEUM OF MOMENTS · EST. ∞</span><h1>ZAMANIN<br/><em>ÖTESİNDE</em></h1><p>Dün, bugün ve henüz yaşanmamış yarın arasında.</p><a className="cta" href="#story">YOLCULUĞA BAŞLA <b>↓</b></a></div><ClockFace className="hero-clock"/><div className="coordinates">41°01' N&nbsp;&nbsp; 28°58' E<br/>A TIME / A PLACE / A MOMENT</div><Timekeeper compact message="Tick... tock... Hazırsan, zamanı birlikte katlayalım."/><a href="#story" className="scroll-hint">SCROLL TO TRAVEL <span>↓</span></a></section>
 <section id="story" className="story section"><header><span className="chapter">01 / KÖKEN</span><h2>ZAMANI ÖLÇME<br/><em>İHTİYACI</em></h2></header><div className="story-body"><p className="lead">İnsanlık zamanı önce gökyüzünde gördü. Gölgenin uzamasında, ayın dönüşünde ve mevsimlerin sabrında.</p><div className="history-line">{['GÜNEŞ','GÖLGE','AY','SU','DİŞLİ','SİNYAL'].map((x)=><span key={x}>{x}</span>)}</div><Timekeeper message="Saatleri icat etmedik. Önce hayatımızı anlamlandırmak için zamanın izini sürdük."/></div></section>
 <section id="history" className="collection section"><div className="section-heading"><span className="chapter">02 / ARŞİV</span><h2>ZAMANI ÖLÇEN<br/><em>MAKİNELER</em></h2><p>Her mekanizma, insanın sonsuzluğu sayılabilir kılma arzusundan doğdu.</p></div><div className="clock-rail">{clocks.map((clock)=><button className={'clock-card '+(selected.title===clock.title?'active':'')} onClick={()=>setSelected(clock)} key={clock.title}><span className="card-icon">{clock.icon}</span><small>{clock.era} · {clock.year}</small><strong>{clock.title}</strong><i>+</i></button>)}</div><div className="selected-clock"><div className="object"><span>{selected.icon}</span><div className="orbit one"/><div className="orbit two"/></div><div><span className="chapter">{selected.year} / {selected.era}</span><h3>{selected.title}</h3><p>{selected.description}</p><dl><dt>Konum</dt><dd>Zaman çizgisi · aktif kayıt</dd><dt>İlke</dt><dd>Ritmi görünür kılmak</dd></dl></div><Timekeeper message={selected.message}/></div></section>
 <section className="travel section"><div className="travel-sticky"><span className="chapter">03 / GEÇİŞ</span><div className="eras"><b>PAST</b><i/><b>PRESENT</b><i/><b>FUTURE</b></div><p>Geçmiş, şimdi ve gelecek aynı saatin farklı yüzleri.</p><div className="year">20<span>26</span></div></div></section>
 <section className="timeless-section section"><span className="chapter">04 / DENEY</span><h2>YA ZAMAN<br/><em>OLMASAYDI?</em></h2><button className="toggle" onClick={()=>setTimeless(!timeless)} aria-pressed={timeless}><span>{timeless?'TIMELESS':'NORMAL'}</span><i/></button><p>Saatler durur. Parçacıklar susar. Peki hayat da ilerlemeyi bırakır mıydı?</p><ClockFace className="still-clock"/><Timekeeper message={timeless?'Her şey sustuğunda bile, içimizdeki zaman yürümeye devam eder.':'Zamanı durdurabilseydik... hayat da ilerlemeyi bırakır mıydı?'}/></section>
 <section id="lab" className="lab section"><span className="chapter">05 / CLOCK LAB</span><h2>İÇİNİ AÇ,<br/><em>ZAMANI GÖR.</em></h2><div className="lab-layout"><div className="exploded"><div className="gear g1">⚙</div><div className="gear g2">⚙</div><div className="gear g3">⚙</div><ClockFace/><span className="pin p1">01 · DİŞLİ</span><span className="pin p2">02 · AKREP</span><span className="pin p3">03 · YAY</span></div><div className="lab-copy"><p>Bir saat, zamanı yaratmaz. Sadece onu görünür kılan küçük anlaşmalar kurar.</p><button className="text-button" onClick={()=>setSelected(clocks[3])}>MEKANİZMA HAKKINDA KONUŞ <b>→</b></button><Timekeeper compact message="Dişliler birbirini iterken, her an yerini bir sonrakine bırakır."/></div></div></section>
 <section id="future" className="future section"><div className="future-orb"><span>∞</span></div><span className="chapter">06 / SİNYAL</span><h2>ZAMANIN<br/><em>SONRAKİ YÜZÜ</em></h2><p>Gelecekte zamanı nasıl ölçeceğiz?</p><Timekeeper message="Belki geleceğin saatleri saniyeleri değil, anlamlı anları sayacak."/></section>
 <footer id="about"><ClockFace/><p>TIME NEVER STOPS.<br/><em>NEITHER SHOULD YOU.</em></p><small>DEVELOPED BY SELEN ÖNÜGÖREN</small><button onClick={restart}>RESTART TIME ↻</button></footer>
 </main>
}
export default App
